CREATE FUNCTION pg_temp.ok(label text,condition boolean) RETURNS text LANGUAGE plpgsql AS $$ BEGIN IF condition IS DISTINCT FROM true THEN RAISE EXCEPTION 'FAIL %',label;END IF;RETURN 'PASS '||label;END $$;
SELECT pg_temp.ok('worker cannot read authentication sessions directly',NOT has_table_privilege('service_role','auth.sessions','SELECT'));
INSERT INTO auth.users SELECT x::uuid FROM unnest(ARRAY['11111111-1111-1111-1111-111111111111','22222222-2222-2222-2222-222222222222','33333333-3333-3333-3333-333333333333','44444444-4444-4444-4444-444444444444']) x;
