SELECT pg_temp.ok('source session helper is exclusive to worker',
 has_function_privilege('service_role','private.atlas_source_session_exists(uuid,uuid)','EXECUTE')
 AND NOT has_function_privilege('anon','private.atlas_source_session_exists(uuid,uuid)','EXECUTE')
 AND NOT has_function_privilege('authenticated','private.atlas_source_session_exists(uuid,uuid)','EXECUTE'));
SET LOCAL ROLE anon;
DO $$ BEGIN BEGIN PERFORM private.atlas_source_session_exists('11111111-1111-1111-1111-111111111111','00000000-0000-0000-0000-000000000001');RAISE EXCEPTION 'anonymous session probe accepted' USING ERRCODE='XX000';EXCEPTION WHEN insufficient_privilege THEN NULL;END;END $$;
RESET ROLE;
SET LOCAL ROLE authenticated;
DO $$ BEGIN BEGIN PERFORM private.atlas_source_session_exists('11111111-1111-1111-1111-111111111111','00000000-0000-0000-0000-000000000001');RAISE EXCEPTION 'human session probe accepted' USING ERRCODE='XX000';EXCEPTION WHEN insufficient_privilege THEN NULL;END;END $$;
RESET ROLE;
SET LOCAL ROLE service_role;
SELECT pg_temp.ok('source session helper verifies exact owner',private.atlas_source_session_exists('11111111-1111-1111-1111-111111111111','00000000-0000-0000-0000-000000000001')
 AND NOT private.atlas_source_session_exists('22222222-2222-2222-2222-222222222222','00000000-0000-0000-0000-000000000001'));
SELECT pg_temp.ok('source session helper rejects missing session',NOT private.atlas_source_session_exists('11111111-1111-1111-1111-111111111111',NULL)
 AND NOT private.atlas_source_session_exists('11111111-1111-1111-1111-111111111111','00000000-0000-0000-0000-000000000099'));
DO $$ BEGIN BEGIN PERFORM 1 FROM auth.sessions;RAISE EXCEPTION 'worker read sessions directly' USING ERRCODE='XX000';EXCEPTION WHEN insufficient_privilege THEN NULL;END;END $$;
SELECT pg_temp.ok('helper does not grant session table access',true);
RESET ROLE;
