ALTER FUNCTION private.atlas_manager_work(timestamptz,uuid,uuid) RENAME TO atlas_manager_real_work;
CREATE FUNCTION private.atlas_manager_work(p_at timestamptz,p_owner uuid,p_person uuid) RETURNS timestamptz LANGUAGE sql STABLE AS $$ SELECT CASE WHEN current_setting('atlas.fixture_business',true)='on' THEN p_at WHEN current_setting('atlas.fixture_business',true)='closed' THEN p_at+interval '3 days' ELSE private.atlas_manager_real_work(p_at,p_owner,p_person) END $$;
