CREATE FUNCTION pg_temp.fixture_job(message text) RETURNS uuid LANGUAGE plpgsql AS $$
DECLARE r uuid:=gen_random_uuid();j uuid:=gen_random_uuid();
BEGIN
 INSERT INTO atlas_runs(id,owner_id,request_id,conversation_id,request_client_id,request_message,status) VALUES(r,'11111111-1111-1111-1111-111111111111',gen_random_uuid(),'99999999-9999-9999-9999-999999999999','aaaaaaaa-aaaa-aaaa-aaaa-aaaaaaaaaaaa',message,'completed');
 INSERT INTO atlas_jobs(id,owner_id,conversation_id,origin_run_id,client_id,title,task,status,lease_token,lease_until,source_session_id) VALUES(j,'11111111-1111-1111-1111-111111111111','99999999-9999-9999-9999-999999999999',r,'aaaaaaaa-aaaa-aaaa-aaaa-aaaaaaaaaaaa','Consulta FICTÍCIA','Conferir registro.','running','dddddddd-dddd-dddd-dddd-dddddddddddd',now()+interval '4 minutes','00000000-0000-0000-0000-000000000001');
 RETURN j;
END $$;
SAVEPOINT clock_case;
SELECT set_config('atlas.fixture_job',pg_temp.fixture_job('O vídeo foi postado?')::text,true) IS NOT NULL;
SET LOCAL atlas.fixture_business='closed';
SET LOCAL ROLE service_role;
SELECT set_config('request.jwt.claims','{"role":"service_role"}',true) IS NOT NULL;
SELECT pg_temp.ok('outside hours schedules without calling',(public.atlas_manager_consult(current_setting('atlas.fixture_job')::uuid,'dddddddd-dddd-dddd-dddd-dddddddddddd','aaaaaaaa-aaaa-aaaa-aaaa-aaaaaaaaaaaa','66666666-6666-6666-6666-666666666661','Pode conferir o andamento da publicação?',NULL)->>'state')='scheduled');
SELECT pg_temp.ok('no off-hours Atlas message',(SELECT count(*) FROM atlas_team_messages m JOIN atlas_team_threads t ON t.id=m.thread_id WHERE t.origin_job_id=current_setting('atlas.fixture_job')::uuid)=0);
SELECT public.atlas_worker_finish(current_setting('atlas.fixture_job')::uuid,'dddddddd-dddd-dddd-dddd-dddddddddddd','completed','Consulta agendada.',NULL,'[]','{}');
SET LOCAL atlas.fixture_business='on';
SELECT public.atlas_manager_sync_consults();
SELECT public.atlas_manager_sync_consults();
SELECT pg_temp.ok('next business dispatch exactly once',(SELECT count(*) FROM atlas_team_messages m JOIN atlas_team_threads t ON t.id=m.thread_id WHERE t.origin_job_id=current_setting('atlas.fixture_job')::uuid)=1);
RESET ROLE;
UPDATE atlas_jobs SET status='cancelled' WHERE id=current_setting('atlas.fixture_job')::uuid;
SET LOCAL ROLE service_role;
SELECT public.atlas_manager_sync_consults();
SELECT pg_temp.ok('cancelled consultation never returns late',(SELECT status='cancelled' FROM atlas_jobs WHERE id=current_setting('atlas.fixture_job')::uuid) AND (SELECT state='closed' FROM atlas_team_threads WHERE origin_job_id=current_setting('atlas.fixture_job')::uuid));
RESET ROLE;
ROLLBACK TO clock_case;
SAVEPOINT revoked_case;
SELECT set_config('atlas.fixture_job',pg_temp.fixture_job('Confere o andamento?')::text,true) IS NOT NULL;
SET LOCAL ROLE service_role;
SELECT public.atlas_manager_consult(current_setting('atlas.fixture_job')::uuid,'dddddddd-dddd-dddd-dddd-dddddddddddd','aaaaaaaa-aaaa-aaaa-aaaa-aaaaaaaaaaaa','66666666-6666-6666-6666-666666666661','Pode confirmar o andamento da tarefa?',NULL) IS NOT NULL;
SELECT public.atlas_worker_finish(current_setting('atlas.fixture_job')::uuid,'dddddddd-dddd-dddd-dddd-dddddddddddd','completed','Aguardando retorno.',NULL,'[]','{}');
RESET ROLE;
DELETE FROM auth.sessions WHERE id='00000000-0000-0000-0000-000000000001';
SET LOCAL ROLE service_role;
SELECT public.atlas_manager_sync_consults();
SELECT pg_temp.ok('revoked source session blocks return',(SELECT status='failed' FROM atlas_jobs WHERE id=current_setting('atlas.fixture_job')::uuid));
SELECT pg_temp.ok('official followup survives owner logout',(SELECT state='awaiting_reply' FROM atlas_team_threads WHERE origin_job_id='77777777-7777-7777-7777-777777777772'));
RESET ROLE;
ROLLBACK TO revoked_case;
SAVEPOINT reassignment_case;
SELECT set_config('atlas.fixture_job',pg_temp.fixture_job('Confere o andamento?')::text,true) IS NOT NULL;
SET LOCAL ROLE service_role;
SELECT public.atlas_manager_consult(current_setting('atlas.fixture_job')::uuid,'dddddddd-dddd-dddd-dddd-dddddddddddd','aaaaaaaa-aaaa-aaaa-aaaa-aaaaaaaaaaaa','66666666-6666-6666-6666-666666666661','Pode confirmar o andamento da tarefa?',NULL) IS NOT NULL;
SELECT public.atlas_worker_finish(current_setting('atlas.fixture_job')::uuid,'dddddddd-dddd-dddd-dddd-dddddddddddd','completed','Aguardando retorno.',NULL,'[]','{}');
RESET ROLE;
UPDATE tarefas SET assignee_ids=ARRAY['22222222-2222-2222-2222-222222222222'::uuid] WHERE id='66666666-6666-6666-6666-666666666661';
SET LOCAL ROLE authenticated;
SELECT set_config('request.jwt.claims','{"sub":"33333333-3333-3333-3333-333333333333","role":"authenticated","session_id":"00000000-0000-0000-0000-000000000003"}',true) IS NOT NULL;
SELECT pg_temp.ok('former assignee loses consultation access',(SELECT count(*) FROM atlas_team_threads WHERE origin_job_id=current_setting('atlas.fixture_job')::uuid)=0);
RESET ROLE;
SET LOCAL ROLE service_role;
SELECT set_config('request.jwt.claims','{"role":"service_role"}',true) IS NOT NULL;
SELECT public.atlas_manager_sync_consults();
SELECT pg_temp.ok('changed task assignment invalidates stale query',(SELECT status='failed' FROM atlas_jobs WHERE id=current_setting('atlas.fixture_job')::uuid));
RESET ROLE;
ROLLBACK TO reassignment_case;
SAVEPOINT policy_case;
SELECT set_config('atlas.fixture_job',pg_temp.fixture_job('Confere o andamento?')::text,true) IS NOT NULL;
SET LOCAL ROLE service_role;
SELECT set_config('request.jwt.claims','{"role":"service_role"}',true) IS NOT NULL;
DO $$ BEGIN BEGIN PERFORM public.atlas_manager_consult(current_setting('atlas.fixture_job')::uuid,gen_random_uuid(),'aaaaaaaa-aaaa-aaaa-aaaa-aaaaaaaaaaaa',NULL,'Pode confirmar o andamento da conta?',NULL);RAISE EXCEPTION 'wrong lease accepted' USING ERRCODE='XX000';EXCEPTION WHEN insufficient_privilege THEN NULL;END;END $$;
SELECT pg_temp.ok('wrong lease refused before message',NOT EXISTS(SELECT 1 FROM atlas_team_threads WHERE origin_job_id=current_setting('atlas.fixture_job')::uuid));
DO $$ BEGIN BEGIN PERFORM public.atlas_manager_consult(current_setting('atlas.fixture_job')::uuid,'dddddddd-dddd-dddd-dddd-dddddddddddd','aaaaaaaa-aaaa-aaaa-aaaa-aaaaaaaaaaaa',NULL,'PRIVATE_MARKER não compartilhar. Pode conferir a tarefa?',NULL);RAISE EXCEPTION 'private quote accepted' USING ERRCODE='XX000';EXCEPTION WHEN invalid_parameter_value THEN NULL;END;END $$;
SELECT pg_temp.ok('private knowledge quote refused before dispatch',NOT EXISTS(SELECT 1 FROM atlas_team_threads WHERE origin_job_id=current_setting('atlas.fixture_job')::uuid));
SELECT public.atlas_manager_consult(current_setting('atlas.fixture_job')::uuid,'dddddddd-dddd-dddd-dddd-dddddddddddd','aaaaaaaa-aaaa-aaaa-aaaa-aaaaaaaaaaaa',NULL,'Pode confirmar o andamento da conta?',NULL) IS NOT NULL;
SELECT public.atlas_worker_finish(current_setting('atlas.fixture_job')::uuid,'dddddddd-dddd-dddd-dddd-dddddddddddd','completed','Aguardando retorno.',NULL,'[]','{}');
RESET ROLE;
INSERT INTO atlas_manager_accounts(owner_id,client_id,person_id,updated_by) VALUES('11111111-1111-1111-1111-111111111111','aaaaaaaa-aaaa-aaaa-aaaa-aaaaaaaaaaaa','44444444-4444-4444-4444-444444444444','11111111-1111-1111-1111-111111111111');
SET LOCAL ROLE service_role;
SELECT public.atlas_manager_sync_consults();
SELECT pg_temp.ok('changed account invalidates stale query',(SELECT status='failed' FROM atlas_jobs WHERE id=current_setting('atlas.fixture_job')::uuid));
RESET ROLE;
ROLLBACK TO policy_case;
SAVEPOINT moved_task_case;
SELECT set_config('atlas.fixture_job',pg_temp.fixture_job('Confere a publicação?')::text,true) IS NOT NULL;
SET LOCAL ROLE service_role;
SELECT set_config('request.jwt.claims','{"role":"service_role"}',true) IS NOT NULL;
SELECT public.atlas_manager_consult(current_setting('atlas.fixture_job')::uuid,'dddddddd-dddd-dddd-dddd-dddddddddddd','aaaaaaaa-aaaa-aaaa-aaaa-aaaaaaaaaaaa','66666666-6666-6666-6666-666666666661','Consegue confirmar o andamento com o executor?','22222222-2222-2222-2222-222222222222') IS NOT NULL;
SELECT public.atlas_worker_finish(current_setting('atlas.fixture_job')::uuid,'dddddddd-dddd-dddd-dddd-dddddddddddd','completed','Aguardando a conta.',NULL,'[]','{}');
RESET ROLE;
UPDATE tarefas SET client_id='bbbbbbbb-bbbb-bbbb-bbbb-bbbbbbbbbbbb' WHERE id='66666666-6666-6666-6666-666666666661';
SELECT pg_temp.ok('task moved across clients invalidates account consultation',NOT private.atlas_consult_current((SELECT id FROM atlas_team_threads WHERE origin_job_id=current_setting('atlas.fixture_job')::uuid)));
SET LOCAL ROLE service_role;
SELECT public.atlas_manager_sync_consults();
SELECT pg_temp.ok('moved task cannot return a stale answer',(SELECT status='failed' FROM atlas_jobs WHERE id=current_setting('atlas.fixture_job')::uuid));
RESET ROLE;
ROLLBACK TO moved_task_case;
SAVEPOINT independent_orders_case;
SELECT set_config('atlas.fixture_first',pg_temp.fixture_job('Preciso criar uma campanha de vídeo.')::text,true) IS NOT NULL;
SELECT set_config('atlas.fixture_second',pg_temp.fixture_job('Preciso organizar a apuração dos resultados.')::text,true) IS NOT NULL;
SET LOCAL ROLE service_role;
SELECT set_config('request.jwt.claims','{"role":"service_role"}',true) IS NOT NULL;
SELECT public.atlas_manager_consult(current_setting('atlas.fixture_first')::uuid,'dddddddd-dddd-dddd-dddd-dddddddddddd','aaaaaaaa-aaaa-aaaa-aaaa-aaaaaaaaaaaa',NULL,'Vamos esclarecer a campanha que precisa de vídeo.',NULL,'organize') IS NOT NULL;
SELECT public.atlas_manager_consult(current_setting('atlas.fixture_second')::uuid,'dddddddd-dddd-dddd-dddd-dddddddddddd','aaaaaaaa-aaaa-aaaa-aaaa-aaaaaaaaaaaa',NULL,'Vamos esclarecer a apuração dos resultados combinados.',NULL,'organize') IS NOT NULL;
SELECT pg_temp.ok('independent owner orders keep separate origins',(SELECT count(*) FROM atlas_team_threads WHERE origin_job_id IN(current_setting('atlas.fixture_first')::uuid,current_setting('atlas.fixture_second')::uuid) AND management_kind='intake')=2);
SELECT pg_temp.ok('repeated owner order reuses its own thread',(public.atlas_manager_consult(current_setting('atlas.fixture_first')::uuid,'dddddddd-dddd-dddd-dddd-dddddddddddd','aaaaaaaa-aaaa-aaaa-aaaa-aaaaaaaaaaaa',NULL,'Vamos esclarecer a campanha que precisa de vídeo.',NULL,'organize')->>'reused')::boolean);
RESET ROLE;
ROLLBACK TO independent_orders_case;
SAVEPOINT idea_case;
SELECT set_config('atlas.fixture_job',pg_temp.fixture_job('E se fizéssemos uma campanha nova?')::text,true) IS NOT NULL;
SET LOCAL ROLE service_role;
SELECT set_config('request.jwt.claims','{"role":"service_role"}',true) IS NOT NULL;
SELECT pg_temp.ok('idea does not become execution',(public.atlas_manager_consult(current_setting('atlas.fixture_job')::uuid,'dddddddd-dddd-dddd-dddd-dddddddddddd','aaaaaaaa-aaaa-aaaa-aaaa-aaaaaaaaaaaa',NULL,'Organizar uma campanha que ainda é hipótese.',NULL,'organize')->>'available')::boolean=false);
SELECT pg_temp.ok('idea creates no task or staff question',NOT EXISTS(SELECT 1 FROM atlas_team_threads WHERE origin_job_id=current_setting('atlas.fixture_job')::uuid) AND (SELECT count(*) FROM tarefas)=5);
SELECT pg_temp.ok('public RPC machine writes are not available to humans',NOT has_function_privilege('authenticated','public.atlas_manager_consult(uuid,uuid,uuid,uuid,text,uuid,text)','EXECUTE') AND NOT has_function_privilege('anon','public.atlas_manager_sync_consults()','EXECUTE'));
RESET ROLE;
ROLLBACK TO idea_case;
ROLLBACK;
